const fail = (status: number, code: string): never => { throw new AdminImportError(status, code); };
const sourceChanged = (): never => fail(409, 'ADMIN_CATALOG_REVIEW_SOURCE_CHANGED');
const reviewRequired = (): never => fail(409, 'ADMIN_IMPORT_REVIEW_REQUIRED');
const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === 'object' && !Array.isArray(value);
/** Album fields only a review captured for metadata lookup can apply. */
const reviewOnlyFields: ReadonlySet<string> = new Set(['artists', 'label', 'expectedTracklist']);
const pathOf = (field: CatalogReviewField) => field.scope === 'album' ? `album.${field.field}` : `tracks.${field.slotId}.${field.field}`;
const storedDate = (date: ImportDate | null) => date ? { year: date.year, ...(date.month === null ? {} : { month: date.month }), ...(date.day === null ? {} : { day: date.day }) } : {};
const creditRevisionOf = (owner: { creditRevision?: unknown }) => Number.isInteger(owner.creditRevision) ? owner.creditRevision as number : 0;
const visibilityOf = (record: Record<string, unknown>): 'public' | 'hidden' => record.visibility === undefined || record.visibility === 'public' ? 'public' : 'hidden';
/** The review's automatic-write revision (absent or malformed: 0), which lookup applications bump without changing `revision`. */
const valueRevisionOf = (doc: AdminImportDocument) => Number.isSafeInteger(doc.valueRevision) && doc.valueRevision! >= 0 ? doc.valueRevision! : 0;

type AppliedRelease = Awaited<ReturnType<typeof importAppliedLookupRelease>>;
/**
 * The identity model of a format-3 review with a readable capture, from its stored draft, with the names its stored names and its
 * stored run (`record`'s fetched aliases and the `applied` release's credits) found for each ID.
 */
const modelOf = (doc: AdminImportDocument, draft: ImportDraftV2, record: Pick<MetadataLookupRecord, 'aliases'> | null, applied: AppliedRelease): ReviewIdentityModel =>
    catalogReviewIdentityModel({ reviewId: doc._id.toHexString(), slots: doc.manifest.files.map(file => file.slotId), draft, capture: doc.catalogCapture,
        found: reviewFoundNames(doc, draft, applied ? reviewRecordFoundNames(record, applied.candidate.release) : new Map()) });
/** The identity model of `doc` as modelOf builds it, reading its lookup record's aliases and applied release in `session`. */
async function readModel(doc: AdminImportDocument, draft: ImportDraftV2, session: ClientSession): Promise<ReviewIdentityModel> {
    const applied = await importAppliedLookupRelease(doc._id, session);
    return modelOf(doc, draft, applied ? await importLookupRecord(doc._id, session, { aliases: 1 }) : null, applied);
}
/** A stored pair of the applied pairing, when well formed. */
const isPair = (pair: unknown): pair is ExpectedTracklistPair => isRecord(pair) && typeof pair.slotId === 'string' && Number.isSafeInteger(pair.discNumber)
    && Number.isSafeInteger(pair.trackNumber);
/** The applied pairing's pairs: null when it is missing or any pair is malformed (a partial pairing would place nothing reliably). */
const pairsOf = (value: unknown): ExpectedTracklistPair[] | null => Array.isArray(value) && value.every(isPair) ? value : null;

/**
 * Marks the rows of decided reuse or replace targets that changed since their decision (no longer ready, or at another identity
 * revision), read in one bounded query per kind, so the confirmation shows the row an apply would refuse as stale.
 */
async function markChangedTargets(resolution: ReviewIdentityResolution, session: ClientSession): Promise<void> {
    for (const kind of ['artist', 'organization'] as const) {
        const targets = resolution.reuseTargets.filter(target => target.kind === kind), ids = [...new Set(targets.map(target => target.id))];
        if (!ids.length) continue;
        const rows = await getDb()!.collection(IMPORT_CANDIDATE_COLLECTIONS[kind]).find({ _id: { $in: ids.map(value => new ObjectId(value)) }, ...readyImportCandidate(kind) },
            { session, projection: importCandidateProjection }).limit(ids.length).maxTimeMS(3_000).toArray();
        const revisions = new Map(rows.map(row => [row._id.toHexString(), importCandidateRevision(row)]));
        for (const target of targets) {
            if (revisions.get(target.id) === target.revision) continue;
            const row = target.owner === 'label' ? resolution.label : resolution.scoped.find(item => item.identity.handle === target.owner)?.outcome;
            if (row) row.needsAnswer = true;
        }
    }
}

/**
 * GET /catalog-reviews/:id/candidates: the identity rows of the review's default selection (every applicable Artist entry list
 * that changed, and the label when it may change and changed), their Artist and Organization candidates, the preselections and
 * MusicBrainz ID writes an apply of that selection must show, the Album's and each member's current and new Credits, and the
 * review's `revision` and `valueRevision` an apply binds. A row needs an answer whenever an apply would wait for it: unanswered,
 * behind a refusal resolution reports (resolveCatalogReviewIdentities), or with a decided reuse or replace target that changed
 * since its decision. An apply that deselects lists or the label computes these items and rows narrowed by identity. An applied review, or one not captured for metadata lookup (format 3), has none; an unreadable capture asks
 * for a reload, and a source that is not current is 409 source changed. Writes nothing; candidate reads past their budget are a 503.
 */
export function getCatalogReviewCandidates(actor: string, id: string): Promise<CatalogReviewIdentityResponse> {
    if (!objectId(id)) return Promise.reject(new AdminImportError(404, 'ADMIN_CATALOG_REVIEW_NOT_FOUND'));
    return withImportAdmin(actor, async session => {
        const doc = await importCollection().findOne({ _id: new ObjectId(id), purpose: 'catalogReview' }, { session });
        if (!doc) return fail(404, 'ADMIN_CATALOG_REVIEW_NOT_FOUND');
        const empty: CatalogReviewIdentityResponse = { revision: doc.revision, valueRevision: valueRevisionOf(doc), identities: [], label: null, candidates: { items: [], unavailable: [] },
            preselections: [], musicBrainzIds: [], album: null, members: [] };
        if (doc.catalogApplied || importDraftVersion(doc) !== CATALOG_REVIEW_DRAFT_V3) return empty;
        if (!readableCatalogCapture(doc)) return fail(409, 'ADMIN_IMPORT_RELOAD_REQUIRED');
        // A stale review shows no confirmation: its bound rows would name records as they no longer are.
        if ((await readCatalogReviewSource(doc, session)).status !== 'current') return sourceChanged();
        const draft = storedDraftV2(doc), model = await readModel(doc, draft, session), selection = defaultReviewSelection(model);
        const resolution = await resolveCatalogReviewIdentities({ doc, draft, model, selection, decisions: doc.catalogIdentityDecisions, operationId: null }, session);
        await markChangedTargets(resolution, session);
        const bound = [...resolution.scoped.flatMap(item => item.identity.bound.map(record => ({ kind: 'artist' as const, record }))),
            ...(resolution.label && model.label.bound ? [{ kind: 'organization' as const, record: model.label.bound }] : [])];
        const visibility = new Map<string, 'public' | 'hidden'>();
        for (const kind of ['artist', 'organization'] as const) {
            const ids = [...new Set(bound.filter(item => item.kind === kind).map(item => item.record.id))];
            if (!ids.length) continue;
            const rows = await getDb()!.collection(IMPORT_CANDIDATE_COLLECTIONS[kind]).find({ _id: { $in: ids.map(value => new ObjectId(value)) }, ...readyImportCandidate(kind) },
                { session, projection: { visibility: 1 } }).limit(ids.length).maxTimeMS(3_000).toArray();
            for (const row of rows) visibility.set(`${kind}:${row._id.toHexString()}`, visibilityOf(row));
        }
        const view = (kind: 'artist' | 'organization', record: ReviewBoundRecord): CatalogReviewBoundRecord =>
            ({ id: record.id, name: record.name, musicBrainzId: record.musicBrainzId, revision: record.revision, visibility: visibility.get(`${kind}:${record.id}`) ?? 'public' });
        // Credit names: captured records as captured, candidates by their names, and records still to be created by their identity's.
        const names = new Map<string, string>();
        for (const item of model.lists) for (const credit of item.capturedCredits) if (isRecord(credit.subject) && typeof credit.subject.name === 'string') names.set(`${credit.subjectType}:${credit.subjectId}`, credit.subject.name);
        for (const item of resolution.candidates.items) names.set(`${item.kind}:${item.id}`, item.label);
        for (const record of resolution.creates) names.set(`${record.kind}:${record.id}`, record.name);
        const label = model.label;
        return {
            revision: doc.revision, valueRevision: valueRevisionOf(doc),
            identities: resolution.scoped.map(({ identity, outcome }) => ({ id: identity.handle, name: identity.name, musicBrainzId: identity.musicBrainzId, names: identity.names,
                entries: identity.entries.map(item => ({ path: item.path, slotId: item.slotId, entryKey: item.entry.key, name: item.entry.name, role: item.entry.role })),
                state: identity.state, bound: identity.bound.map(record => view('artist', record)), decision: outcome.decision, preselection: outcome.preselection,
                needsAnswer: outcome.needsAnswer, musicBrainzIdWrite: outcome.write })),
            label: resolution.label && label.current ? { name: label.current.name, musicBrainzId: label.current.musicBrainzId, state: label.bound ? 'bound' : 'unbound',
                bound: label.bound ? view('organization', label.bound) : null, decision: resolution.label.decision, preselection: resolution.label.preselection,
                needsAnswer: resolution.label.needsAnswer, musicBrainzIdWrite: resolution.label.write } : null,
            candidates: { items: resolution.candidates.items, unavailable: resolution.candidates.unavailable as { kind: 'artist' | 'organization'; label: string }[] },
            preselections: resolution.preselections, musicBrainzIds: resolution.idWrites,
            ...reviewCreditViews(model, resolution, selection, names)
        };
    });
}

/** A reuse or replace target, read ready in `session`: it must still be at the revision decided, and a replace target must keep another ID. */
async function assertDecidedTarget(kind: 'artist' | 'organization', decision: { action: string; candidateId: string | null; candidateRevision: string | null }, entryId: string | null,
    session: ClientSession): Promise<void> {
    if (decision.action === 'create-distinct') return;
    const target = await getDb()!.collection(IMPORT_CANDIDATE_COLLECTIONS[kind]).findOne({ _id: new ObjectId(decision.candidateId!), ...readyImportCandidate(kind) }, { session, projection: importCandidateProjection });
    if (!target || importCandidateRevision(target) !== decision.candidateRevision) fail(409, 'ADMIN_IMPORT_DUPLICATE_STALE');
    if (decision.action === 'replace') { const held = keepableMusicBrainzId(target!.musicBrainzId); if (!held || held === entryId) fail(409, 'ADMIN_IMPORT_DUPLICATE_STALE'); }
}

/**
 * POST /catalog-reviews/:id/decisions `{operationId, expectedRevision, decisions}`: replaces the review's identity decisions with a
 * `decisions` receipt. Admitted only for a format-3 review (409 ADMIN_IMPORT_LOOKUP_REFUSED) with a readable capture (409 reload)
 * whose source is current (409 source changed). Each item names an identity of the default selection's lists, or the label while
 * it is selected by default: a handle naming no such identity (one a lookup application replaced since the read) or the label
 * while it is not selected is 409 ADMIN_IMPORT_DECISION_STALE, and so is a name other than the identity's current one. A bound
 * identity or label admits only replacing its record's ID (the record at its captured revision, which must keep another ID, and
 * an identity that carries one), a conflicting identity only reuse or create, and replace needs an identity ID (else 400). A reuse
 * or replace target that is not ready, at another revision or (replace) keeps no other ID, or a replace whose new ID another ready
 * record holds, is 409 ADMIN_IMPORT_DUPLICATE_STALE. Within one list, bound records and the records decisions reuse must be
 * distinct, and no decided ID write may land on a record (or ID) another write of the set lands on (400). Each decision binds its
 * identity's current MusicBrainz ID; draft value origins are unchanged. A bound identity's replace that became invalid is answered
 * by a set without it: the record keeps its ID.
 */
export function decideCatalogReviewIdentities(actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> {
    const body = parseAdminProjectMutation(raw, ['decisions']), items = parseReviewIdentityDecisions(body.decisions);
    return mutateAdminProject(actor, id, body, 'decisions', async (doc, session) => {
        if (importDraftVersion(doc) !== CATALOG_REVIEW_DRAFT_V3) return fail(409, 'ADMIN_IMPORT_LOOKUP_REFUSED');
        const draft = storedDraftV2(doc);
        if (!readableCatalogCapture(doc)) return fail(409, 'ADMIN_IMPORT_RELOAD_REQUIRED');
        if ((await readCatalogReviewSource(doc, session)).status !== 'current') return sourceChanged();
        const model = await readModel(doc, draft, session), selection = defaultReviewSelection(model), selected = new Set(selection.lists), label = model.label;
        const scoped = model.identities.filter(identity => identity.entries.some(item => selected.has(item.path)));
        const decisions: CatalogReviewIdentityDecision[] = [];
        for (const item of items) {
            if (item.scope === 'artist') {
                const identity = scoped.find(candidate => candidate.handle === item.identity);
                if (!identity) return fail(409, 'ADMIN_IMPORT_DECISION_STALE');
                const bound = identity.bound[0];
                if (identity.state === 'bound' ? item.action !== 'replace' || !identity.musicBrainzId || item.candidateId !== bound.id || item.candidateRevision !== bound.revision
                    : identity.state === 'conflicting' ? item.action === 'replace' : item.action === 'replace' && !identity.musicBrainzId) return invalidImport();
                if (item.boundName !== identity.name) return fail(409, 'ADMIN_IMPORT_DECISION_STALE');
                await assertDecidedTarget('artist', item, identity.musicBrainzId, session);
                decisions.push({ ...item, boundMusicBrainzId: identity.musicBrainzId });
                continue;
            }
            const current = label.current;
            if (!selection.label || !current) return fail(409, 'ADMIN_IMPORT_DECISION_STALE');
            if (label.bound ? item.action !== 'replace' || !current.musicBrainzId || item.candidateId !== label.bound.id || item.candidateRevision !== label.bound.revision
                : item.action === 'replace' && !current.musicBrainzId) return invalidImport();
            if (item.boundName !== current.name) return fail(409, 'ADMIN_IMPORT_DECISION_STALE');
            await assertDecidedTarget('organization', item, current.musicBrainzId, session);
            decisions.push({ ...item, boundMusicBrainzId: current.musicBrainzId });
        }
        // Two entries of one list never reuse one Artist: bound records and decided reuses of each list are distinct.
        for (const list of model.lists.filter(item => selected.has(item.path))) {
            const records = list.current.flatMap(entry => {
                const identity = model.identities.find(candidate => candidate.entries.some(at => at.path === list.path && at.entry.key === entry.key))!;
                const own = identity.entries.find(at => at.path === list.path && at.entry.key === entry.key)!.boundTo;
                if (own) return [own.id];
                if (identity.state === 'bound') return [identity.bound[0].id];
                const decision = decisions.find(candidate => candidate.scope === 'artist' && candidate.identity === identity.handle);
                return decision && decision.action !== 'create-distinct' ? [decision.candidateId!] : [];
            });
            if (new Set(records).size !== records.length) return invalidImport();
        }
        // The set resolved as an apply would, with ID holders read now: a replace whose new ID another record holds is stale, and a
        // decided write landing on a record or ID another write of the set lands on (say, two lists reusing one record that keeps no
        // ID, each recording its own) can never apply.
        const resolution = await resolveCatalogReviewIdentities({ doc, draft, model, selection, decisions, operationId: null }, session, decisionCheckReads(session));
        if (resolution.invalidDecisions.length) return fail(409, 'ADMIN_IMPORT_DUPLICATE_STALE');
        if (resolution.collidingDecisions.length) return invalidImport();
        doc.catalogIdentityDecisions = decisions;
    }, catalogReviewProjectPolicy);
}

/**
 * A parsed apply body: the fingerprinted body and its parts (missing preselections and ID writes count as empty; a missing
 * `expectedValueRevision` is null).
 */
type ApplyInput = { body: ReturnType<typeof parseAdminProjectMutation>; fields: CatalogReviewField[]; memberCredits: string[];
    preselections: CatalogReviewShownPreselection[]; musicBrainzIds: CatalogReviewShownIdWrite[]; expectedValueRevision: number | null };
/**
 * Parses `{operationId, expectedRevision, fields, preselections?, musicBrainzIds?, memberCredits?, expectedValueRevision?}` before
 * the intent is fingerprinted: the fields (parseCatalogReviewFields, `[]` admitted), at most 100 distinct member slot UUIDs, the
 * shown preselections and ID writes (each at most 513 well-formed items) and the `valueRevision` the confirmation read (a
 * non-negative safe integer). At least one field or member is selected. A body selecting the Album's Artist entries, label or
 * expected tracklist carries both shown lists; one listing members may leave them out (empty, so an apply refuses whenever it
 * computes items). Both, and any body listing a member, carry `expectedValueRevision`, since lookup writes those values without
 * changing `revision`. An apply from an editor that shows no identity rows sends `fields` only. Anything else is invalid input.
 */
export function parseCatalogReviewApplyBody(raw: unknown): ApplyInput {
    const body = parseAdminProjectMutation(raw, ['fields', 'preselections', 'musicBrainzIds', 'memberCredits', 'expectedValueRevision']);
    const fields = parseCatalogReviewFields(body.fields, { allowEmpty: true });
    const members = hasOwn(body, 'memberCredits') ? body.memberCredits : [];
    if (!Array.isArray(members) || members.length > CATALOG_REVIEW_MAX_MEMBER_CREDITS || members.some(slot => !uuid(slot)) || new Set(members).size !== members.length) return invalidImport();
    const preselections = hasOwn(body, 'preselections') ? parseShownPreselections(body.preselections) : null;
    const musicBrainzIds = hasOwn(body, 'musicBrainzIds') ? parseShownIdWrites(body.musicBrainzIds) : null;
    const valueRevision = hasOwn(body, 'expectedValueRevision') ? body.expectedValueRevision : null;
    if (hasOwn(body, 'expectedValueRevision') && (!Number.isSafeInteger(valueRevision) || (valueRevision as number) < 0)) return invalidImport();
    if (!fields.length && !members.length) return invalidImport();
    const reviewOnly = fields.some(field => field.scope === 'album' && reviewOnlyFields.has(field.field));
    if (reviewOnly && (preselections === null || musicBrainzIds === null)) return invalidImport();
    if ((reviewOnly || members.length > 0) && valueRevision === null) return invalidImport();
    return { body, fields, memberCredits: members as string[], preselections: preselections ?? [], musicBrainzIds: musicBrainzIds ?? [],
        expectedValueRevision: valueRevision as number | null };
}

/** Errors the catalog writes raise for state that changed since the review was read, as the review's refusals. */
function applyRefusal(error: unknown): unknown {
    if (isMusicBrainzIdDuplicateKey(error)) return new AdminImportError(409, 'ADMIN_CATALOG_REVIEW_IDENTITY_CHANGED');
    if (error instanceof CatalogCreditConflictError || error instanceof ArtistReferenceUnavailableError || error instanceof OrganizationReferenceUnavailableError
        || error instanceof AudioTrackReferenceUnavailableError || error instanceof AlbumReferenceUnavailableError) return new AdminImportError(409, 'ADMIN_CATALOG_REVIEW_SOURCE_CHANGED');
    if (error instanceof CatalogCreditValidationError) return new AdminImportError(400, 'ADMIN_IMPORT_INVALID_INPUT');
    return error;
}

/**
 * POST /catalog-reviews/:id/apply. Writes the selected saved values in one transaction with the automatic Album order and the
 * receipt, after these checks, each refusing before any write: analysis active (409), a metadata lookup run that can still send a
 * request (409 ADMIN_IMPORT_LOOKUP_ACTIVE), an `expectedValueRevision` other than the review's (409
 * ADMIN_IMPORT_REVISION_CONFLICT: a lookup application wrote values since the confirmation was read), a source that is not current,
 * captured Credit subjects included (409 source changed), a review-only selection on a review not captured for lookup (400), a
 * selected value with an unanswered lookup conflict (409 ADMIN_IMPORT_REVIEW_REQUIRED), a selection that may not apply (400; a Disc
 * Number only for a track that captured one; an Artist entry list, label, member list or expected tracklist only while it differs
 * from what the review captured, an entry list only while applicable (catalogReviewIdentityModel: never one naming an Artist twice
 * whatever is decided), the tracklist only as the applied release offers it with its whole pairing readable; titles, dates and
 * numbers are applied as saved), a placement violation (400:
 * a selected expected tracklist must place every paired member at its row after the selected changes, and a Disc or Track Number a
 * pairing filled applies only as its pair says, with that tracklist or a kept tracklist that places it), then, when Artist
 * entries, the label or a member are selected, the identities (shown preselections or ID writes other than those computed now, or
 * a row needing an answer: unanswered, a decided replace another record's ID now blocks, a decided ID write colliding with another,
 * or one list resolving one Artist twice: 409 ADMIN_IMPORT_REVIEW_REQUIRED, each such row marked in GET /candidates, whose items
 * an apply of a narrower selection computes narrowed by identity; a decided record
 * that changed: 409 ADMIN_IMPORT_DUPLICATE_STALE) and each changing owner's stored Credits (409 source changed). A
 * Credit list the Credit rules refuse is 400; Credit writes turned off are a 503. Then: reference fences, the identity fence, new
 * Artists and label Organizations (the Album's visibility, IDs derived from review, operation and identity), ID writes on reused
 * records (only while they hold what was reviewed), member Credits (documented), Track values, Album Credits (documented, which
 * also keeps each Artist's `albumIds`), the Album's values, order and expected tracklist, and the receipt. A MusicBrainz ID another
 * record took is 409 ADMIN_CATALOG_REVIEW_IDENTITY_CHANGED; a fence or Credit lifecycle conflict is 409 source changed.
 */
export async function applyCatalogReview(actor: string, id: string, raw: unknown): Promise<CatalogReviewResponse> {
    const input = parseCatalogReviewApplyBody(raw);
    try { return await mutateAdminProject(actor, id, input.body, 'apply', (doc, session) => applyReview(doc, session, input, actor), catalogReviewProjectPolicy); }
    catch (error) { throw applyRefusal(error); }
}

/** The apply change of applyCatalogReview, run by mutateAdminProject as `actor` in `session`. */
async function applyReview(doc: AdminImportDocument, session: ClientSession, input: ApplyInput, actor: string): Promise<void> {
    const { fields, memberCredits, body } = input, db = getDb()!;
    if (['queued', 'running'].includes(doc.analysis.state) || doc.analysis.chunks.some(chunk => chunk.state === 'inflight')) return fail(409, 'ADMIN_IMPORT_ANALYSIS_ACTIVE');
    // The run's own state, read in this transaction, decides, never the review's lookup gate: an earlier release's worker ends a
    // review run without updating that gate. A run past its grant, or while lookup is unavailable, never sends again, so it never
    // holds apply (turning imports off cannot leave a review unappliable). A run can only become active through a change that
    // writes the review document, which this apply replaces, so a concurrent change conflicts and is retried.
    const run = await importLookupRecord(doc._id, session, { state: 1, grantExpiresAt: 1, run: 1, applied: 1, aliases: 1 });
    if (lookupRunActive(run, new Date(), metadataLookupConfiguration().available)) return fail(409, 'ADMIN_IMPORT_LOOKUP_ACTIVE');
    // A run that completed after the confirmation was read wrote values without changing `revision`: nothing it wrote was confirmed.
    if (input.expectedValueRevision !== null && input.expectedValueRevision !== valueRevisionOf(doc)) return fail(409, 'ADMIN_IMPORT_REVISION_CONFLICT');
    const source = await readCatalogReviewSource(doc, session);
    if (source.status !== 'current') return sourceChanged();
    const { album, tracks } = source, draft = storedDraftV2(doc), sourceTracks = doc.catalogSource!.tracks;
    const albumFields = new Set(fields.filter(field => field.scope === 'album').map(field => field.field));
    const captured = importDraftVersion(doc) === CATALOG_REVIEW_DRAFT_V3 && readableCatalogCapture(doc);
    if ((memberCredits.length || [...albumFields].some(field => reviewOnlyFields.has(field))) && !captured) return invalidImport();
    const needed = new Set<string>(lookupAnswersNeeded(run, doc, { append: false }).conflicts);
    if ([...fields.map(pathOf), ...memberCredits.map(slotId => `tracks.${slotId}.artists`)].some(path => needed.has(path))) return reviewRequired();
    const applied = captured ? await importAppliedLookupRelease(doc._id, session) : null, model = captured ? modelOf(doc, draft, run, applied) : null;
    // Each selected value must be one this review can apply.
    const albumPatch: Record<string, unknown> = {}, trackPatches = new Map<string, Record<string, unknown>>();
    for (const field of fields) {
        if (field.scope === 'album') {
            if (field.field === 'title') albumPatch.title = cleanText(draft.album.title, 300);
            else if (field.field === 'releaseDate') albumPatch.releaseDate = storedDate(draft.album.releaseDate);
            else if (field.field === 'artists' && !(model!.lists[0].applicable && model!.lists[0].changed)) return invalidImport();
            else if (field.field === 'label' && !(model!.label.applicable && model!.label.changed && model!.label.current)) return invalidImport();
            continue;
        }
        const original = sourceTracks.find(track => track.slotId === field.slotId), trackDraft = draft.tracks.find(track => track.slotId === field.slotId);
        if (!original || !trackDraft || (field.field === 'discNumber' && !catalogReviewSourceDisc(original))) return invalidImport();
        const patch = trackPatches.get(original.id) ?? {};
        patch[field.field] = field.field === 'title' ? cleanText(trackDraft.title, 300) : field.field === 'discNumber' ? parseDiscNumber(trackDraft.discNumber) : trackDraft.trackNumber;
        trackPatches.set(original.id, patch);
    }
    for (const slotId of memberCredits) {
        const list = model!.lists.find(item => item.slotId === slotId);
        if (!list || !list.applicable || !list.changed) return invalidImport();
    }
    // Only lookup writes automatic values in a review: such a number came from the applied pairing, and applies only as it says.
    const automatic = fields.filter(field => (field.field === 'discNumber' || field.field === 'trackNumber') && originOf(doc.draftOrigins, pathOf(field)) === 'automatic');
    // The tracklist and pairing-filled numbers are placed against the whole stored pairing: one unreadable pair refuses them.
    const capture = doc.catalogCapture, decoded = pairsOf(run?.applied?.pairs), pairs = decoded ?? [];
    if ((albumFields.has('expectedTracklist') || automatic.length) && !decoded) return invalidImport();
    let tracklist: { rows: ExpectedTracklistRow[]; source: 'musicbrainz' | 'itunes' } | null = null;
    if (albumFields.has('expectedTracklist')) {
        const rows = parseExpectedTracklistRows((draft.album as { expectedTracklist?: unknown }).expectedTracklist);
        if (!rows.ok || sameDraftValue(rows.rows, capture?.album.expectedTracklist ?? null)) return invalidImport();
        if (!applied) return invalidImport();
        const offered = expectedTracklistFromRelease(applied.candidate.release!), release = 'rows' in offered ? parseExpectedTracklistRows(offered.rows) : null;
        if (!release?.ok || !sameDraftValue(rows.rows, release.rows)) return invalidImport();
        tracklist = { rows: rows.rows, source: applied.applied.source === 'itunes' ? 'itunes' : 'musicbrainz' };
    }
    // Placement: each member's numbers after the selected changes (a captured value where its number is not selected).
    const selectedPath = new Set(fields.map(pathOf));
    const numbers = new Map(sourceTracks.map(track => {
        const trackDraft = draft.tracks.find(item => item.slotId === track.slotId);
        return [track.slotId, { discNumber: selectedPath.has(`tracks.${track.slotId}.discNumber`) ? trackDraft?.discNumber ?? null : catalogReviewSourceDisc(track)?.value ?? null,
            trackNumber: selectedPath.has(`tracks.${track.slotId}.trackNumber`) ? trackDraft?.trackNumber ?? null : track.trackNumber }];
    }));
    if (tracklist && !expectedTracklistPlaced(tracklist.rows, pairs, numbers).placed) return invalidImport();
    if (automatic.length) {
        for (const field of automatic) {
            const pair = pairs.find(item => item.slotId === field.slotId), value = draft.tracks.find(track => track.slotId === field.slotId)?.[field.field as 'discNumber' | 'trackNumber'];
            if (!pair || pair[field.field as 'discNumber' | 'trackNumber'] !== value) return invalidImport();
        }
        if (!tracklist) {
            const kept = parseExpectedTracklistRows(capture?.album.expectedTracklist), slots = new Set(automatic.map(field => field.slotId));
            if (!kept.ok || !expectedTracklistPlaced(kept.rows, pairs.filter(pair => slots.has(pair.slotId)), numbers).placed) return invalidImport();
        }
    }
    // Identities and Credits, only when Artist entries, the label or a member are selected.
    const selection: ReviewSelection = { lists: [...(albumFields.has('artists') ? ['album.artists'] : []), ...memberCredits.map(slotId => `tracks.${slotId}.artists`)], label: albumFields.has('label') };
    const identities = selection.lists.length || selection.label;
    const resolution = identities ? await resolveCatalogReviewIdentities({ doc, draft, model: model!, selection, decisions: doc.catalogIdentityDecisions, operationId: body.operationId }, session) : null;
    if (resolution && (!sameShownPreselections(input.preselections, resolution.preselections) || resolution.needsAnswer.length || resolution.duplicateInList || resolution.invalidWrite
        || resolution.idWriteCollision || !sameShownIdWrites(input.musicBrainzIds, resolution.idWrites))) return reviewRequired();
    for (const target of resolution?.reuseTargets ?? []) await assertDecidedTarget(target.kind, { action: 'reuse', candidateId: target.id, candidateRevision: target.revision }, null, session);
    let plans: ReturnType<typeof reviewCreditPlans> | null = null;
    if (resolution) {
        try { plans = reviewCreditPlans(model!, resolution, selection, body.operationId); }
        catch (error) { if (error instanceof CatalogCreditValidationError) return invalidImport(); throw error; }
        // The stored Credits each changing owner holds now must be the ones the review captured (an unmigrated Album's linked Artists too).
        const owners: { kind: 'album' | 'audioTrack'; record: any; captured: CatalogCredit[] }[] = [
            ...(plans.album ? [{ kind: 'album' as const, record: album, captured: plans.album.stored }] : []),
            ...[...plans.members].map(([slotId, plan]) => ({ kind: 'audioTrack' as const, record: tracks[sourceTracks.findIndex(track => track.slotId === slotId)], captured: plan.stored }))];
        for (const owner of owners) {
            let current: CatalogCredit[];
            try { current = await legacyCreditsForUnmigratedOwner(session, owner.kind, String(owner.record._id), owner.record); }
            catch (error) { if (error instanceof CatalogCreditValidationError) return sourceChanged(); throw error; }
            if (!sameCredits(current, owner.captured)) return sourceChanged();
        }
        if (plans.album?.changes || [...plans.members.values()].some(plan => plan.changes)) requireCatalogCreditWrites();
    }
    const appliedAt = new Date(), stored = tracklist ? expectedTracklistForStorage(tracklist.source, appliedAt, tracklist.rows) : null;
    if (stored && !stored.ok) return invalidImport();

    // Writes. Read-only revision checks are followed by canonical write fences so concurrent deletes and legacy writers conflict.
    const albumId = doc.catalogSource!.album.id;
    await touchReadyAlbumReferences([albumId], session);
    await touchReadyAudioTrackReferences(sourceTracks.map(track => track.id), session);
    if (resolution) {
        await serializeImportIdentityCommits(session);
        const visibility = visibilityOf(album), actorId = actor;
        for (const record of resolution.creates) {
            if (record.kind === 'artist') await db.collection('artists').insertOne(newArtistRecord({ id: record.id, name: record.name, albumIds: [], actorId, visibility, musicBrainzId: record.musicBrainzId }), { session });
            else await db.collection('organizations').insertOne(newLabelOrganizationRecord({ id: record.id, name: record.name, actorId, visibility, musicBrainzId: record.musicBrainzId }), { session });
        }
        // A reused record gains or replaces its ID only while it still holds what the review saw (an unkeepable stored value is none).
        for (const write of resolution.writes.filter(item => !item.created)) {
            const collection = db.collection(IMPORT_CANDIDATE_COLLECTIONS[write.kind]), filter = { _id: new ObjectId(write.recordId), ...readyImportCandidate(write.kind) };
            const row = await collection.findOne(filter, { session, projection: { musicBrainzId: 1 } });
            if (!row || keepableMusicBrainzId(row.musicBrainzId) !== write.replaces) return sourceChanged();
            if ((await collection.updateOne(filter, { $set: { musicBrainzId: write.musicBrainzId } }, { session })).matchedCount !== 1) return sourceChanged();
        }
        for (const [slotId, plan] of plans!.members) {
            if (!plan.changes) continue;
            const track = tracks[sourceTracks.findIndex(item => item.slotId === slotId)];
            await replaceCatalogCreditsWithinTransaction(session, 'audioTrack', String(track._id), plan.next, 'documented', creditRevisionOf(track));
        }
    }
    for (const [trackId, patch] of trackPatches) {
        // A Disc Number is stored with its catalog-edit source; null removes both keys, as a catalog edit does.
        const { discNumber: disc, ...rest } = patch, hasDisc = hasOwn(patch, 'discNumber');
        await db.collection('audioTracks').updateOne({ _id: new ObjectId(trackId), ...readyAudioStorageFilter }, {
            $set: { ...withCatalogSearchUpdate(rest, 'title'), ...(hasDisc && disc !== null ? { discNumber: disc, discNumberSource: 'admin-catalog' } : {}), updatedAt: new Date() },
            ...(hasDisc && disc === null ? { $unset: { discNumber: '', discNumberSource: '' } } : {}),
            $inc: { adminRevision: 1, referenceRevision: 1 } }, { session });
    }
    // The Album's Credits write also keeps each Artist's albumIds: a new primary gains the Album and a replaced one loses it.
    if (plans?.album?.changes) await replaceCatalogCreditsWithinTransaction(session, 'album', albumId, plans.album.next, 'documented', creditRevisionOf(album));
    if (fields.some(field => field.field === 'trackNumber' || field.field === 'discNumber')) albumPatch.audioTrackIds = await orderedAlbumTrackIds(session, sourceTracks.map(track => track.id));
    if (stored?.ok) albumPatch.expectedTracklist = stored.tracklist;
    if (Object.keys(albumPatch).length) await db.collection('albums').updateOne({ _id: album._id }, { $set: { ...withCatalogSearchUpdate(albumPatch, 'title'), updatedAt: new Date() }, $inc: { adminRevision: 1, referenceRevision: 1 } }, { session });
    doc.catalogApplied = { operationId: body.operationId, at: appliedAt.toISOString(), fields, ...(memberCredits.length ? { memberCredits } : {}) };
}
